@import url('https://fonts.googleapis.com/css2?family=Noto+Serif+SC:wght@400;600&display=swap');

/* ---------- 全局基础（纯浅橙色） ---------- */
body {
    background: #faf0e6; /* 纯浅橙色，无渐变 */
    font-family: 'Noto Serif SC', serif;
}

/* ---------- 聊天消息容器（保留实色卡片） ---------- */
.mes[is_user="false"], .mes[is_user="true"] {
    position: relative !important;
    max-width: 820px !important;
    margin: 40px auto !important;
    padding: 60px 20px 20px 180px !important;
    background: #fff8f0 !important; /* 纯浅橙白，无渐变 */
    border-radius: 24px 24px 24px 8px !important;
    border: 1px solid #e6d5b8 !important;
    box-shadow: 0 8px 20px rgba(0,0,0,0.08) !important;
    overflow: visible !important;
}

/* 梅花枝装饰 */
.mes::before {
    content: "" !important;
    position: absolute !important;
    left: -20px !important;
    top: 0 !important;
    width: 380px !important;
    height: 220px !important;
    background-image: url('https://s1.imagehub.cc/images/2026/04/05/b0fc90f62ec5f1cd0003b3dd61ce7f95.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: left top !important;
    pointer-events: none !important;
    z-index: 15 !important;
    filter: drop-shadow(2px 2px 6px rgba(0,0,0,0.15)) !important;
}

/* 左侧底纹：完全移除渐变，仅保留纯浅橙色 + 波点纹理（无透明过渡） */
.mes::after {
    content: "" !important;
    position: absolute !important;
    left: -20px !important;
    top: 0 !important;
    width: 200px !important;
    height: 100% !important;
    /* 核心修改：删掉所有radial-gradient渐变，只保留纯浅橙色 + 波点纹理 */
    background: #faf0e6 !important; /* 纯浅橙色，和全局背景一致，无任何渐变 */
    /* 仅保留波点纹理，且纹理不透明，颜色匹配浅橙风格 */
    background-image: url("data:image/svg+xml,%3Csvg width='100' height='100' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M11 18c3.866 0 7-3.134 7-7s-3.134-7-7-7-7 3.134-7 7 3.134 7 7 7zm48 25c3.866 0 7-3.134 7-7s-3.134-7-7-7-7 3.134-7 7 3.134 7 7 7zm-43-7c1.657 0 3-1.343 3-3s-1.343-3-3-3-3 1.343-3 3 1.343 3 3 3zm63 31c1.657 0 3-1.343 3-3s-1.343-3-3-3-3 1.343-3 3 1.343 3 3 3zM34 90c1.657 0 3-1.343 3-3s-1.343-3-3-3-3 1.343-3 3 1.343 3 3 3zm56-76c1.657 0 3-1.343 3-3s-1.343-3-3-3-3 1.343-3 3 1.343 3 3 3zM12 86c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm28-65c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm23-11c2.76 0 5-2.24 5-5s-2.24-5-5-5-5 2.24-5 5 2.24 5 5 5zm-6 60c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm29 22c2.76 0 5-2.24 5-5s-2.24-5-5-5-5 2.24-5 5 2.24 5 5 5zM32 63c2.76 0 5-2.24 5-5s-2.24-5-5-5-5 2.24-5 5 2.24 5 5 5zm57-13c2.76 0 5-2.24 5-5s-2.24-5-5-5-5 2.24-5 5 2.24 5 5 5zm-9-21c1.105 0 2-.895 2-2s-.895-2-2-2-2 .895-2 2 .895 2 2 2zM60 91c1.105 0 2-.895 2-2s-.895-2-2-2-2 .895-2 2 .895 2 2 2zM35 41c1.105 0 2-.895 2-2s-.895-2-2-2-2 .895-2 2 .895 2 2 2zM12 60c1.105 0 2-.895 2-2s-.895-2-2-2-2 .895-2 2 .895 2 2 2z' fill='%236b4c3b' fill-opacity='0.03' fill-rule='evenodd'/%3E%3C/svg%3E") !important;
    background-size: 80px 80px !important; /* 仅保留波点纹理尺寸 */
    background-repeat: repeat !important; /* 仅保留波点重复 */
    pointer-events: none !important;
    z-index: 10 !important;
}

/* ---------- 头像：放大 + 右移（修正被切边） ---------- */
.mes .avatar {
    position: absolute !important;
    left: -5px !important;
    top: -25px !important;
    width: 90px !important;
    height: 90px !important;
    border-radius: 50% !important;
    border: 3px solid #b87c4f !important;
    background: #fff0e0 !important; /* 纯浅橙，无渐变 */
    box-shadow: 2px 4px 10px rgba(0,0,0,0.1) !important;
    overflow: hidden !important;
    z-index: 14 !important;
}

.mes .avatar img {
    width: 100% !important;
    height: 100% !important;
    object-fit: cover !important;
    border-radius: 50% !important;
}

/* ---------- 文字及按钮层级 ---------- */
.mes .name_text,
.mes .timestamp,
.mes .mes_time,
.mes_text,
.mes_buttons {
    position: relative !important;
    z-index: 20 !important;
}

.mes .name_text {
    font-size: 1.6rem !important;
    color: #6b4c3b !important;
    border-left: 3px solid #c28a5c !important;
    padding-left: 12px !important;
    margin-bottom: 6px !important;
    display: inline-block !important;
}

.mes .timestamp, .mes .mes_time {
    font-size: 11px !important;
    color: #9b8a72 !important;
    margin-left: 12px !important;
}

.mes_text {
    font-family: 'Noto Serif SC', serif !important;
    font-size: 15px !important;
    line-height: 1.75 !important;
    color: #3e2a23 !important;
    text-align: justify !important;
    padding: 0 12px !important;
    border-left: 2px solid #e2d4c0 !important;
    margin-top: 12px !important;
}

.mes_text blockquote {
    border-left: 3px solid #c28a5c !important;
    background: #faf1e4 !important; /* 纯浅橙，无渐变 */
    padding: 8px 16px !important;
    font-style: italic !important;
    color: #5e3a2e !important;
}

.mes_text strong, .mes_text b { color: #b34e3a !important; font-weight: 600 !important; }
.mes_text em, .mes_text i { color: #8b694a !important; }
/* ========================================
   彻底统一橙色
======================================== */

:root {
    --uni-orange: #e67e22;   /* 统一橙色，可改为 #ffa500 或 #f39c12 */
    --uni-orange-light: #f8b56c;
}

/* ---------- 1. 账号/用户设置区域（你提到的 .userAccount） ---------- */
.userAccount,
.userAccount *,
.account-settings,
.user-settings-card,
.avatar-settings,
.api-key-area {
    border-color: var(--uni-orange) !important;
}

.userAccount {
    background: rgba(230, 126, 34, 0.1) !important;
    border: 1px solid var(--uni-orange) !important;
    border-radius: 0 !important;
}

/* 账号区域内的按钮、输入框也统一 */
.userAccount input,
.userAccount button,
.userAccount select {
    border-color: var(--uni-orange) !important;
}

/* ---------- 2. 所有分类标题（确保覆盖） ---------- */
.inline-drawer-header,
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#top-settings-holder h4:not(#ai-config-button *):not(#rightNavHolder),
.standoutHeader strong, 
#right-nav-panel h2,
.drawer-content > h3,
.drawer-content .flex-container h3:first-of-type,
.popup h3:not(dialog),
.userAccount h3, .userAccount h4 {
    background: var(--uni-orange) !important;
    background-image: none !important;
    border-radius: 0 !important;
    border: 1px solid var(--uni-orange) !important;
    color: #ffffff !important;
}

/* 标题前的装饰方块改为白色 */
.standoutHeader strong::before,
#right-nav-panel h2::before,
.drawer-content > h3::before,
.popup h3:not(dialog *)::before {
    color: #ffffff !important;
}

/* ---------- 3. 所有灰色边框/分割线/文字改为橙色 ---------- */
/* 侧边栏、面板边框 */
#left-nav-panel, #right-nav-panel,
.drawer-content, .popup, dialog, .modal {
    border-color: var(--uni-orange) !important;
}

/* 分割线 */
hr, .separator, .divider,
.standoutHeader:not(h4), #rm_PinAndTabs,
#AdvancedFormatting .flex-container.alignItemsBaseline:not(h3),
#WorldInfo .alignitemscenter:not(#world_popup) {
    border-bottom: 1px dashed var(--uni-orange) !important;
}

/* 辅助文字、提示文本 */
.help-text, .hint, .subdued, .text-muted,
.setting-description, .form-text,
.mes_time, .timestamp,
.userAccount .help-text, .userAccount small {
    color: var(--uni-orange) !important;
}

/* 滚动条 */
::-webkit-scrollbar-track { background: #fff0e0 !important; }
::-webkit-scrollbar-thumb { background: var(--uni-orange) !important; }

/* 世界书条目、预设卡片 */
.wi-card-entry, .world_entry,
#completion_prompt_manager .completion_prompt_manager_prompt {
    background: rgba(230, 126, 34, 0.1) !important;
    border-color: var(--uni-orange) !important;
}

/* 输入框、下拉框、复选框 */
input[type="text"], input[type="number"], textarea, select,
input[type="checkbox"], input[type="radio"] {
    border-color: var(--uni-orange) !important;
}
input[type="checkbox"]:checked,
input[type="radio"]:checked {
    background-color: var(--uni-orange) !important;
    accent-color: var(--uni-orange) !important;
}

/* ---------- 4. 交互特效（聚焦发光 + 点击缩放） ---------- */
input[type="text"]:focus, input[type="number"]:focus,
textarea:focus, select:focus {
    border-color: var(--uni-orange) !important;
    box-shadow: 0 0 8px var(--uni-orange) !important;
    outline: none !important;
    background-color: #fffef7 !important;
}
========================================
   功能性界面
======================================== */

:root {
    /* 橙色变量（统一色值，可自行修改） */
    --func-orange: #ffcc80;      /* 浅橙色背景 */
    --func-orange-dark: #f5a623; /* 深橙色边框/强调 */
    --func-orange-text: #5d3a1a; /* 深棕色文字（保证对比度） */
    --func-orange-light: #ffe0b5;/* 悬停或辅助色 */
}

/* ---------- 1. 所有渐变背景 → 纯浅橙色 + 方形 ---------- */
.inline-drawer-header,
.standoutHeader,
.drawer-content > h3,
#right-nav-panel h2,
.popup h3,
#completion_prompt_manager .completion_prompt_manager_header,
#completion_prompt_manager .completion_prompt_manager_list_separator hr,
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt,
.menu_button,
input[type="text"], input[type="number"], textarea, select,
.wi-card-entry, .world_entry,
.userAccount,
.avatar-container.selected,
#qr--bar .qr--button,
#toast-container .toast {
    background: var(--func-orange) !important;
    background-image: none !important;  /* 移除所有渐变 */
    border-radius: 0 !important;        /* 方形直角 */
}

/* 特殊处理：分割线的渐变 → 纯色 */
#completion_prompt_manager .completion_prompt_manager_list_separator hr {
    background: var(--func-orange-dark) !important;
    background-image: none !important;
}

/* ---------- 2. 所有灰色边框/分割线 → 橙色 ---------- */
.drawer-content, .popup, dialog, .modal,
#left-nav-panel, #right-nav-panel,
.inline-drawer-header,
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt,
input, textarea, select, button,
.menu_button, .qr--button {
    border-color: var(--func-orange-dark) !important;
}

hr, .separator, .divider,
.standoutHeader:not(h4), #rm_PinAndTabs,
#AdvancedFormatting .flex-container.alignItemsBaseline:not(h3) {
    border-bottom: 1px dashed var(--func-orange-dark) !important;
}

.help-text, .hint, .subdued, .text-muted,
.setting-description, .form-text,
.mes_time, .timestamp,
#completion_prompt_manager .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name {
    color: var(--func-orange-text) !important;
}

.inline-drawer-header,
.standoutHeader,
.drawer-content > h3,
#right-nav-panel h2,
.popup h3 {
    color: var(--func-orange-text) !important;
}

.menu_button, button {
    color: var(--func-orange-text) !important;
}

input, textarea, select {
    background: #fff8f0 !important;
    color: #2c1e12 !important;
}

::-webkit-scrollbar-track {
    background: var(--func-orange-light) !important;
}
::-webkit-scrollbar-thumb {
    background: var(--func-orange-dark) !important;
}

input[type="checkbox"]:checked,
input[type="radio"]:checked {
    background-color: var(--func-orange-dark) !important;
    border-color: var(--func-orange-dark) !important;
}
input[type="range"]::-webkit-slider-thumb {
    background: var(--func-orange-dark) !important;
}
input[type="range"]::-moz-range-thumb {
    background: var(--func-orange-dark) !important;
}
/* ========== 仅修复：弹窗提示文字 = 黑色 ========== */
#toast-container .toast,
#toast-container .toast-message,
.modal-content,
.modal-content *:not(.modal-header *, .modal-footer *),
.popup .content,
.popup .content *:not(.popup-header *),
.reminder-box,
.reminder-box *,
.help-text,
.hint,
.text-muted,
.setting-description {
    color: #000000 !important;
    font-weight: 500 !important;
}
